<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <iostream>
#include <algorithm>
#include <cmath>
using namespace std;

long long gcd(int a, int b) {
    while (b != 0) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

long long lcm(int a, int b) {
    return (long long)a * b / gcd(a, b);
}

double compute_difference(int x1, int y1, int x2, int y2) {
    long long l = lcm(y1, y2);
    long long diff = abs(l / y1 * x1 - l / y2 * x2);
    return (double)diff / l;
}

int main() {
    int x, y, n;
    cin >> x >> y >> n;
    double min_value = 1e9;
    int min_b = 1;
    double t1 = (double)x / y;

    for (int i = 1; i <= n; ++i) {
        int left = 1, right = 1000000;
        while (right - left > 1) {
            int mid = (left + right) / 2;
            double t2 = (double)mid / i;
            if (t2 < t1)
                left = mid;
            else
                right = mid;
        }
        int candidate = left;
        double val_left = compute_difference(candidate, i, x, y);
        double val_right = compute_difference(right, i, x, y);
        int chosen = (val_left < val_right) ? candidate : right;
        double current_diff = compute_difference(chosen, i, x, y);
        double min_diff = compute_difference(min_value, min_b, x, y);
        if (current_diff < min_diff) {
            min_value = chosen;
            min_b = i;
        }
    }
    cout << min_value << "/" << min_b;
    return 0;
}
